import React, { useState } from "react";
import "./ClientsList.css";

const Clients = [
  { id: 1, title: "Cliente 1" },
  { id: 2, title: "Cliente 2" },
  { id: 3, title: "Cliente 3" },
];

const ClientsList = () => {
  const [query, setQuery] = useState("");

  const [clientFilters, setClientFilters] = useState({});

s
  const [activeClient, setActiveClient] = useState(null);

  // 🔍 filtro general (buscador)
  const filteredClients = Clients.filter((c) =>
    c.title.toLowerCase().includes(query.toLowerCase())
  );

  // 🧠 aplicar filtros de cada cliente (preparado para futuro)
  const applyClientFilters = (client) => {
    const filters = clientFilters[client.id];

    if (!filters) return true; // si no hay filtros, mostrar

    // 👉 filtro extra dinámico (puedes escalar este switch)
    if (filters.type === "startsWith") {
      return client.title.toLowerCase().startsWith(filters.value);
    }

    if (filters.type === "includes") {
      return client.title.toLowerCase().includes(filters.value);
    }

    return true;
  };

  // 🔧 actualizar filtros dinámicos
  const handleFilterChange = (clientId, field, value) => {
    setClientFilters((prev) => ({
      ...prev,
      [clientId]: {
        ...prev[clientId],
        [field]: value,
      },
    }));
  };

  return (
    <div>
      <h2>Clientes</h2>

      {/* 🔍 BUSCADOR GLOBAL */}
      <input
        type="text"
        placeholder="Buscar cliente..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />

      {/* LISTA */}
      {filteredClients
        .filter(applyClientFilters)
        .map((client) => (
          <div key={client.id}>
            <h3>{client.title}</h3>

            {/* BOTÓN FILTRO */}
            <button
              onClick={() =>
                setActiveClient(
                  activeClient === client.id ? null : client.id
                )
              }
            >
              Filtro
            </button>

            {/* PANEL DE FILTRO POR CLIENTE */}
            {activeClient === client.id && (
              <div>
                <p>Tipo de filtro:</p>

                <select
                  onChange={(e) =>
                    handleFilterChange(
                      client.id,
                      "type",
                      e.target.value
                    )
                  }
                >
                  <option value="">Sin filtro</option>
                  <option value="includes">Contiene</option>
                  <option value="startsWith">Empieza con</option>
                </select>

                <p>Valor:</p>

                <input
                  type="text"
                  placeholder="Valor..."
                  onChange={(e) =>
                    handleFilterChange(
                      client.id,
                      "value",
                      e.target.value.toLowerCase()
                    )
                  }
                />
              </div>
            )}
          </div>
        ))}
    </div>
  );
};

export default ClientsList;
